// This script assumes the 'data' variable has already been defined elsewhere.

/**
 * Renders a given list of records to the #filter-records element.
 * @param {Array<Object>} records - The array of writeup objects to display.
 */
function displayRecords(records) {
    var output = '<div class="row grid divide-y divide-gray-500">';

    if (Array.isArray(records)) {
        $.each(records, function (key, val) {
            if (val && val.title && val.link) {
                // This is the original link style with the hover effect
                output += `<div class="row antialiased p-2">
                              <a href="${val.link}" target="_blank" rel="noopener nofollow noreferrer">
                                  ✍️ ${val.title}
                              </a>
                           </div>`;
            }
        });
    }

    output += `</div>`;
    $('#filter-records').html(output);
}


/**
 * Filters the main 'data' array based on a query and then displays the results.
 * @param {string} query - The search term entered by the user.
 */
function performSearch(query) {
    var searchField = query;

    if (!searchField || searchField.trim() === '') {
        // If the search bar is cleared, show the random writeups again.
        displayInitialWriteups();
        return;
    }

    var t0 = performance.now();
    var results = [];

    try {
        var regex = new RegExp(searchField, "i");
    } catch (e) {
        console.error("Invalid regex:", e);
        $('#filter-records').html('<div class="p-4 text-center text-red-500">Invalid search pattern.</div>');
        return;
    }

    if (typeof data !== 'undefined' && Array.isArray(data)) {
        results = data.filter(val =>
            val && ((val.title && val.title.search(regex) !== -1) || (val.link && val.link.search(regex) !== -1))
        );
    }

    displayRecords(results);

    var t1 = performance.now();
    var sanitizedSearchField = removeTags(searchField);
    $("#filter-records").prepend(`<div class="text-bold text-center mb-8">Found <code>${results.length}</code> resources related to <b>${sanitizedSearchField}</b> in <code>${(t1 - t0).toFixed(2)} ms</code></div>`);
}


/**
 * Shuffles the main data array and displays the first 1337 results.
 */
function displayInitialWriteups() {
    if (typeof data !== 'undefined' && Array.isArray(data)) {
        // Fisher-Yates shuffle algorithm to randomize the array
        const shuffled = [...data]; // Create a copy to not modify the original
        let currentIndex = shuffled.length, randomIndex;

        // While there remain elements to shuffle.
        while (currentIndex != 0) {
            // Pick a remaining element.
            randomIndex = Math.floor(Math.random() * currentIndex);
            currentIndex--;

            // And swap it with the current element.
            [shuffled[currentIndex], shuffled[randomIndex]] = [shuffled[randomIndex], shuffled[currentIndex]];
        }

        // Take the first 1337 items from the now-randomized array
        const randomRecords = shuffled.slice(0, 1337);

        displayRecords(randomRecords);
        $("#filter-records").prepend(`<div class="text-bold text-center mb-8">Showing 1337 random writeups. Use the search bar to find more.</div>`);
    }
}


// --- Utility Functions ---

function removeTags(html) {
    if (!html) return '';
    var tagBody = '(?:[^"\'>]|"[^"]*"|\'[^\']*\')*';
    var tagOrComment = new RegExp('<(?:' + '!--(?:(?:-*[^->])*--+|-?)' + '|script\\b' + tagBody + '>[\\s\\S]*?</script\\s*' + '|style\\b' + tagBody + '>[\\s\\S]*?</style\\s*' + '|/?[a-z]' + tagBody + ')>', 'gi');
    var oldHtml;
    var sanitizedHtml = String(html);
    do {
        oldHtml = sanitizedHtml;
        sanitizedHtml = sanitizedHtml.replace(tagOrComment, '');
    } while (sanitizedHtml !== oldHtml);
    return sanitizedHtml.replace(/</g, '<');
}

function Remove(el) {
    if (el && el.parentNode) {
        el.parentNode.removeChild(el);
    }
}


// --- Initialization and Event Listeners ---

$(document).ready(function () {

    // --- Add this new section for the popup ---
    const popup = $('#update-popup');
    const openBtn = $('#open-updates-popup');
    const closeBtn = $('.popup-close');

    // Show the popup when the "Check New Updates" link is clicked
    openBtn.on('click', function (e) {
        e.preventDefault(); // Prevents the link from navigating
        popup.css('display', 'flex').hide().fadeIn(200);
    });

    // Hide the popup when the close (X) button is clicked
    closeBtn.on('click', function () {
        popup.fadeOut(200);
    });

    // Hide the popup when the user clicks on the dark overlay area
    popup.on('click', function (e) {
        if (e.target === this) {
            popup.fadeOut(200);
        }
    });

    // Hide the popup when the user presses the Escape key
    $(document).on('keyup', function (e) {
        if (e.key === "Escape") {
            popup.fadeOut(200);
        }
    });

    // Keyup event for the main search bar
    $('#txt-search').keyup(function () {
        performSearch($(this).val());
    });

    // Click event for the category filter buttons
    $('.searchfilter').click(function () {
        var query = $(this).val();
        $('#txt-search').val(query);
        performSearch(query);
    });

    // Handle initial page load
    const urlParams = new URLSearchParams(window.location.search);
    const param = urlParams.get('q');
    if (param) {
        // If there's a search query in the URL, perform that search
        $('#txt-search').val(param);
        performSearch(param);
    } else {
        // Otherwise, display 1337 random writeups by default
        displayInitialWriteups();
    }
});